  const state=await readV2State(root),config=await readV2Config(root),captures=old.groups.flatMap(g=>g.payload.captureIds),scope=new Set(captures);
  if(scope.size!==captures.length||Object.values(state.submissions).some(s=>s.payload.captureIds.some(c=>scope.has(c))))throw Error('An existing submission owns this scope; no preparation refresh permitted');
