  const now=new Date().toISOString(),relative=`artifacts/card-processing-v2/browser-jobs/refresh-${id}-${randomUUID()}.json`,bytes=JSON.stringify({kind:'v2-never-bound-preparation-refresh',observedAt:now,previousFrozenJob:old,nextJobId:nextId,unchangedCaptureIds:captures,verifiedOriginals:sourceHashes,externalWrites:0,newIntents:0},null,2);await fs.writeFile(path.join(root,relative),bytes,{flag:'wx',flush:true});const proof={path:relative,sha256:sha(bytes)},next:V2BrowserJob={version:1,id:nextId,stage:'awaiting-reconciliation',groups,at:old.at,updatedAt:now,refreshOf:id,refreshEvidence:proof,canPublish:false,pricing:'deferred-preserved'};
  await save(root,next);old.stage='superseded';old.supersededBy=nextId;old.refreshEvidence=proof;await save(root,old);return next;
