  if(old.stage!=='awaiting-reconciliation'||old.lease||old.csvPath||old.csvSha256||old.uploadEvidence||old.bulkPlanPath||old.groups.some(g=>g.key))throw Error('Only never-bound unleased preparation may partition; reconcile existing intent/upload');
  const state=await readV2State(root),config=await readV2Config(root),captureIds=old.groups.flatMap(g=>g.payload.captureIds),scope=new Set(captureIds);
  if(scope.size!==captureIds.length||Object.values(state.submissions).some(sub=>sub.payload.captureIds.some(c=>scope.has(c))))throw Error('Existing submission owns a partition capture');
  const originals=[];for(const g of old.groups){const members=Object.values(state.cards).filter(c=>g.payload.captureIds.includes(c.captureId)),representative=members.find(c=>c.sku===g.payload.sku),category=config.categories.find(c=>c.categoryId===representative?.identity?.categoryId);
   if(!representative||!category||members.length!==g.payload.captureIds.length||digest(members.map(c=>c.id).sort())!==digest([...g.cardIds].sort())||members.some(c=>c.groupId!==g.groupId||c.draftId||c.stage!=='prepared'||c.issues.length||!c.identity)||Object.values(state.cards).some(c=>c.groupId===g.groupId&&!scope.has(c.captureId))||digest(state.prepared[g.groupId])!==digest(g.payload))throw Error('Exact unchanged prepared partition members/payload required; refresh corrected preparation first');
   if(digest(preparePayload(representative,members,category,representative.photos.map(p=>state.media[p.hash])))!==digest(g.payload))throw Error('Current partition preparation changed');
   const sourceRoot=(await fs.realpath(config.folder)).toLowerCase();for(const c of members)for(const photo of c.photos){const st=await fs.lstat(photo.path);if(!st.isFile()||st.isSymbolicLink()||st.size>35000000||path.dirname(await fs.realpath(photo.path)).toLowerCase()!==sourceRoot||sha(await fs.readFile(photo.path))!==photo.hash)throw Error('Partition original source/hash changed');originals.push({cardId:c.id,captureId:c.captureId,...photo});}
  }
  const existing=await listV2BrowserJobs(root);if(existing.some(j=>j.id!==id&&!nextIds.includes(j.id)&&j.stage!=='superseded'&&j.groups.some(g=>g.payload.captureIds.some(c=>scope.has(c)))))throw Error('Foreign browser job overlaps partition captures');
  const relative=`artifacts/card-processing-v2/browser-jobs/partition-${id}-${digest(nextIds)}.json`,file=path.join(root,relative),now=new Date().toISOString();let proof:{path:string;sha256:string};
  try{const bytes=await fs.readFile(file),prior=JSON.parse(bytes.toString('utf8'));if(prior.kind!=='v2-never-bound-preparation-partition'||digest(prior.previousFrozenJob)!==digest(old)||digest(prior.childJobIds)!==digest(nextIds)||prior.reason!==request.reason)throw Error('Retained partition plan changed; do not overwrite');proof={path:relative,sha256:sha(bytes)};}catch(e){if((e as NodeJS.ErrnoException).code!=='ENOENT')throw e;const bytes=JSON.stringify({kind:'v2-never-bound-preparation-partition',observedAt:now,reason:request.reason,previousFrozenJob:old,childJobIds:nextIds,partitions:parts.map(p=>({jobId:p.id,groupIds:p.groups.map(g=>g.groupId),captureIds:p.groups.flatMap(g=>g.payload.captureIds)})),verifiedOriginals:originals,newIntents:0,externalWrites:0,cardStateWrites:0},null,2);await fs.writeFile(file,bytes,{flag:'wx',flush:true});proof={path:relative,sha256:sha(bytes)};}
  const children:V2BrowserJob[]=[];for(const part of parts){const prior=existing.find(j=>j.id===part.id);if(prior){if(prior.partitionOf!==id||digest(prior.partitionEvidence)!==digest(proof)||prior.stage!=='awaiting-reconciliation'||prior.lease||prior.csvPath||prior.uploadEvidence||prior.groups.some(g=>g.key)||digest(prior.groups)!==digest(part.groups))throw Error('Existing partition child changed or progressed; reconcile same IDs');children.push(prior);continue;}const child:V2BrowserJob={version:1,id:part.id,stage:'awaiting-reconciliation',groups:part.groups,at:old.at,updatedAt:now,partitionOf:id,partitionEvidence:proof,canPublish:false,pricing:'deferred-preserved'};await save(root,child);children.push(child);}
  old.stage='superseded';old.partitionedInto=nextIds;old.partitionEvidence=proof;old.blocker='Never-bound preparation partitioned; resume exact recorded child jobs';await save(root,old);return children;
